{
  "timeline": [
    {
      "date": "1822",
      "headline": "Birth",
      "text": "Harriet Tubman was born Araminta Ross in Dorchester County, Maryland. The exact date of her birth is unknown, but it is estimated to be around 1822."
    },
    {
      "date": "1849",
      "headline": "Escape from Slavery",
      "text": "Harriet Tubman escaped from slavery in Maryland to Philadelphia, Pennsylvania, using the Underground Railroad."
    },
    {
      "date": "1850",
      "headline": "First Rescue Mission",
      "text": "Tubman returned to Maryland to rescue her niece Kessiah and her two children, marking her first successful mission as a conductor on the Underground Railroad."
    },
    {
      "date": "1850-1860",
      "headline": "Underground Railroad Missions",
      "text": "Over the course of a decade, Harriet Tubman conducted approximately 13 missions to rescue around 70 enslaved people, including family and friends, guiding them to freedom."
    },
    {
      "date": "1861-1865",
      "headline": "Civil War Service",
      "text": "During the American Civil War, Tubman served as an armed scout and spy for the Union Army. She was the first woman to lead an armed expedition in the war, which liberated more than 700 enslaved people in the Combahee River Raid."
    },
    {
      "date": "1869",
      "headline": "Marriage to Nelson Davis",
      "text": "Harriet Tubman married Nelson Davis, a Union veteran, in Auburn, New York."
    },
    {
      "date": "1896",
      "headline": "Women's Suffrage Activism",
      "text": "Tubman became active in the women's suffrage movement, working alongside prominent suffragists like Susan B. Anthony and Elizabeth Cady Stanton."
    },
    {
      "date": "1911",
      "headline": "Admission to Rest Home",
      "text": "Due to declining health, Tubman was admitted to the Harriet Tubman Home for the Aged, which she had helped establish years earlier."
    },
    {
      "date": "1913-03-10",
      "headline": "Death",
      "text": "Harriet Tubman died of pneumonia in Auburn, New York, at the age of approximately 91."
    }
  ]
}

{
  "timeline": [
    {
      "date": "1822",
      "headline": "Foundation of Liberia",
      "text": "The American Colonization Society (ACS) established a colony in West Africa for freed African-American slaves, which would later become Liberia."
    },
    {
      "date": "1847-07-26",
      "headline": "Declaration of Independence",
      "text": "Liberia declared its independence from the American Colonization Society, becoming the first African republic to proclaim independence."
    },
    {
      "date": "1848",
      "headline": "First President",
      "text": "Joseph Jenkins Roberts was elected as the first President of Liberia."
    },
    {
      "date": "1862",
      "headline": "U.S. Recognition",
      "text": "The United States formally recognized Liberia as an independent nation."
    },
    {
      "date": "1917",
      "headline": "World War I Involvement",
      "text": "Liberia declared war on Germany during World War I, aligning with the Allies."
    },
    {
      "date": "1944",
      "headline": "President William Tubman",
      "text": "William Tubman became President of Liberia, initiating policies of national unification and economic development."
    },
    {
      "date": "1980-04-12",
      "headline": "Coup d'état",
      "text": "A military coup led by Samuel Doe overthrew President William Tolbert, ending over 130 years of Americo-Liberian political dominance."
    },
    {
      "date": "1989-12-24",
      "headline": "First Liberian Civil War",
      "text": "The First Liberian Civil War began, leading to significant loss of life and displacement."
    },
    {
      "date": "1997-07-19",
      "headline": "Charles Taylor Elected",
      "text": "Charles Taylor was elected President of Liberia following the end of the First Liberian Civil War."
    },
    {
      "date": "1999",
      "headline": "Second Liberian Civil War",
      "text": "The Second Liberian Civil War began, further destabilizing the country."
    },
    {
      "date": "2003-08-11",
      "headline": "Resignation of Charles Taylor",
      "text": "Charles Taylor resigned and went into exile, leading to the end of the Second Liberian Civil War."
    },
    {
      "date": "2005",
      "headline": "Ellen Johnson Sirleaf Elected",
      "text": "Ellen Johnson Sirleaf was elected as the first female President of Liberia and Africa's first elected female head of state."
    },
    {
      "date": "2014",
      "headline": "Ebola Outbreak",
      "text": "Liberia was heavily affected by the West African Ebola outbreak, leading to thousands of deaths."
    },
    {
      "date": "2018-01-22",
      "headline": "George Weah Inaugurated",
      "text": "Former football star George Weah was inaugurated as President of Liberia, succeeding Ellen Johnson Sirleaf."
    }
  ]
}

