{
  "timeline": [
    {
      "date": "-06000",
      "headline": "Settlement of Australia",
      "text": "The first human settlement of Australia by Indigenous Australians is estimated to have occurred around 60,000 years ago."
    },
    {
      "date": "-03500",
      "headline": "Settlement of Papua New Guinea",
      "text": "Papua New Guinea was settled by humans around 35,000 years ago, with evidence of agriculture dating back to 7,000 years ago."
    },
    {
      "date": "-03000",
      "headline": "Settlement of the Solomon Islands",
      "text": "The Solomon Islands were settled by Austronesian peoples around 3,000 years ago."
    },
    {
      "date": "-02000",
      "headline": "Settlement of Fiji",
      "text": "Fiji was settled by Austronesian peoples around 2,000 years ago."
    },
    {
      "date": "-01000",
      "headline": "Settlement of Polynesia",
      "text": "Polynesia began to be settled by Austronesian navigators around 1,000 BCE, with the settlement of Tonga and Samoa."
    },
    {
      "date": "1642",
      "headline": "Discovery by Europeans",
      "text": "Dutch explorer Abel Tasman became the first European to sight Tasmania and New Zealand."
    },
    {
      "date": "1768",
      "headline": "James Cook's First Voyage",
      "text": "British explorer James Cook embarked on his first voyage to the Pacific, leading to the mapping of New Zealand and the east coast of Australia."
    },
    {
      "date": "1788-01-26",
      "headline": "First Fleet Arrives in Australia",
      "text": "The First Fleet of British ships arrived at Port Jackson, establishing the first European colony in Australia."
    },
    {
      "date": "1840",
      "headline": "Treaty of Waitangi",
      "text": "The Treaty of Waitangi was signed between the British Crown and various Māori chiefs, establishing British sovereignty over New Zealand."
    },
    {
      "date": "1901-01-01",
      "headline": "Federation of Australia",
      "text": "The six separate British colonies in Australia federated to form the Commonwealth of Australia."
    },
    {
      "date": "1947",
      "headline": "Independence of Pacific Nations",
      "text": "The post-World War II era saw the gradual independence of Pacific nations, starting with the independence of Samoa in 1962."
    },
    {
      "date": "1975-09-16",
      "headline": "Independence of Papua New Guinea",
      "text": "Papua New Guinea gained independence from Australia."
    },
    {
      "date": "1986",
      "headline": "Australia Act",
      "text": "The Australia Act was passed, severing the final constitutional links between Australia and the United Kingdom."
    },
    {
      "date": "1999",
      "headline": "East Timor Independence Referendum",
      "text": "A UN-sponsored referendum led to East Timor's independence from Indonesia, becoming a sovereign state in 2002."
    }
  ]
}

{
  "timeline": [
    {
      "date": "1965-06-21",
      "headline": "Birth of Lana Wachowski",
      "text": "Lana Wachowski was born on June 21, 1965, in Chicago, Illinois, USA."
    },
    {
      "date": "1967-12-29",
      "headline": "Birth of Lilly Wachowski",
      "text": "Lilly Wachowski was born on December 29, 1967, in Chicago, Illinois, USA."
    },
    {
      "date": "1996",
      "headline": "Debut Film 'Bound'",
      "text": "Lana and Lilly Wachowski made their directorial debut with the film 'Bound', which was released in 1996 and received critical acclaim for its style and storytelling."
    },
    {
      "date": "1999",
      "headline": "Release of 'The Matrix'",
      "text": "The Wachowskis released 'The Matrix', a groundbreaking science fiction film that became a cultural phenomenon, known for its innovative special effects and philosophical themes."
    },
    {
      "date": "2003",
      "headline": "Release of 'The Matrix Reloaded' and 'The Matrix Revolutions'",
      "text": "The Wachowskis released the sequels 'The Matrix Reloaded' and 'The Matrix Revolutions', continuing the story of the original film and expanding its universe."
    },
    {
      "date": "2005",
      "headline": "Release of 'V for Vendetta'",
      "text": "The Wachowskis wrote and produced 'V for Vendetta', a film adaptation of the graphic novel, which was released in 2005 and addressed themes of totalitarianism and resistance."
    },
    {
      "date": "2008",
      "headline": "Release of 'Speed Racer'",
      "text": "The Wachowskis directed 'Speed Racer', a live-action adaptation of the Japanese anime series, known for its vibrant visual style."
    },
    {
      "date": "2012",
      "headline": "Release of 'Cloud Atlas'",
      "text": "The Wachowskis co-directed 'Cloud Atlas', an ambitious film adaptation of David Mitchell's novel, exploring interconnected stories across different time periods."
    },
    {
      "date": "2015",
      "headline": "Release of 'Jupiter Ascending'",
      "text": "The Wachowskis released 'Jupiter Ascending', a science fiction film featuring a complex universe and elaborate visual effects."
    },
    {
      "date": "2015",
      "headline": "Lilly Wachowski Comes Out as Transgender",
      "text": "Lilly Wachowski publicly came out as a transgender woman in 2016, following her sister Lana who had come out in 2012."
    },
    {
      "date": "2015",
      "headline": "Premiere of 'Sense8'",
      "text": "The Wachowskis created the Netflix series 'Sense8', which premiered in 2015, known for its diverse cast and exploration of themes like identity and connection."
    },
    {
      "date": "2021",
      "headline": "Release of 'The Matrix Resurrections'",
      "text": "Lana Wachowski directed 'The Matrix Resurrections', the fourth installment in the Matrix series, which was released in 2021."
    }
  ]
