{
  "timeline": [
    {
      "date": "2023",
      "headline": "Release of 'One Life'",
      "text": "The biographical drama film 'One Life', directed by James Hawes, is released. The film tells the true story of British humanitarian Nicholas Winton, focusing on his efforts to save 669 predominantly Jewish children from German-occupied Czechoslovakia in 1938-39."
    },
    {
      "date": "1938",
      "headline": "Nicholas Winton's Rescue Efforts Begin",
      "text": "Nicholas Winton, a 29-year-old British stockbroker, begins organizing the rescue of Jewish children from Czechoslovakia as the threat of Nazi occupation looms."
    },
    {
      "date": "1939",
      "headline": "Completion of Rescue Operations",
      "text": "By the outbreak of World War II, Nicholas Winton successfully arranges for the safe passage of 669 predominantly Jewish children to Britain, saving them from the impending Holocaust."
    }
  ]
}

{
  "timeline": [
    {
      "date": "1993-07-22",
      "headline": "Birth",
      "text": "Dzhokhar Anzorovich Tsarnaev was born in Tokmok, Kyrgyzstan."
    },
    {
      "date": "2002",
      "headline": "Immigration to the United States",
      "text": "Dzhokhar Tsarnaev and his family immigrated to the United States, settling in Cambridge, Massachusetts."
