      "date": "2011",
      "headline": "Naturalization as a U.S. Citizen",
      "text": "Dzhokhar Tsarnaev became a naturalized U.S. citizen."
    },
    {
      "date": "2013-04-15",
      "headline": "Boston Marathon Bombing",
      "text": "Dzhokhar Tsarnaev and his brother Tamerlan Tsarnaev planted two pressure cooker bombs near the finish line of the Boston Marathon, killing three people and injuring 264 others."
    },
    {
      "date": "2013-04-18",
      "headline": "Murder of Sean Collier",
      "text": "Dzhokhar and Tamerlan Tsarnaev killed MIT police officer Sean Collier in an attempt to steal his gun."
    },
    {
      "date": "2013-04-19",
      "headline": "Capture",
      "text": "Dzhokhar Tsarnaev was captured by police in Watertown, Massachusetts, after a manhunt. His brother Tamerlan was killed in a shootout with police earlier that day."
    },
    {
      "date": "2015-04-08",
      "headline": "Conviction",
      "text": "Dzhokhar Tsarnaev was found guilty on all 30 charges related to the Boston Marathon bombing."
    },
    {
      "date": "2015-05-15",
      "headline": "Sentencing",
      "text": "Dzhokhar Tsarnaev was sentenced to death by lethal injection for his role in the Boston Marathon bombing."
    },
    {
      "date": "2020-07-31",
      "headline": "Death Sentence Overturned",
      "text": "A federal appeals court overturned Dzhokhar Tsarnaev's death sentence, citing errors in the trial."
    },
    {
      "date": "2022-03-04",
      "headline": "Supreme Court Reinstates Death Sentence",
      "text": "The U.S. Supreme Court reinstated the death sentence for Dzhokhar Tsarnaev."
    }
  ]
}

