{
  "timeline": [
    {
      "date": "0360",
      "headline": "First Church Completed",
      "text": "The first church on the site of Hagia Sophia was completed under the orders of Emperor Constantius II. It served as the cathedral of Constantinople."
    },
    {
      "date": "0404",
      "headline": "First Church Destroyed",
      "text": "The first church was largely destroyed during riots that followed the exile of John Chrysostom, the Patriarch of Constantinople."
    },
    {
      "date": "0415",
      "headline": "Second Church Completed",
      "text": "A second church was built on the site by Emperor Theodosius II and was completed in 415."
    },
    {
      "date": "0532",
      "headline": "Second Church Destroyed",
      "text": "The second church was destroyed during the Nika riots, a major uprising against Emperor Justinian I."
    },
    {
      "date": "0537-12-27",
      "headline": "Current Hagia Sophia Completed",
      "text": "The current structure of Hagia Sophia was completed under the orders of Emperor Justinian I. It was designed by the architects Isidore of Miletus and Anthemius of Tralles."
    },
    {
      "date": "1204",
      "headline": "Converted to a Roman Catholic Cathedral",
      "text": "During the Fourth Crusade, Constantinople was captured, and Hagia Sophia was converted into a Roman Catholic cathedral."
    },
    {
      "date": "1261",
      "headline": "Restored as an Eastern Orthodox Cathedral",
      "text": "After the recapture of Constantinople by the Byzantines, Hagia Sophia was restored as an Eastern Orthodox cathedral."
    },
    {
      "date": "1453",
      "headline": "Converted to a Mosque",
      "text": "Following the Ottoman conquest of Constantinople, Sultan Mehmed II converted Hagia Sophia into a mosque."
    },
    {
      "date": "1935",
      "headline": "Converted to a Museum",
      "text": "Under the secular government of Mustafa Kemal Atatürk, Hagia Sophia was secularized and converted into a museum."
    },
    {
      "date": "2020",
      "headline": "Reconverted to a Mosque",
      "text": "Hagia Sophia was reconverted into a mosque following a decree by Turkish President Recep Tayyip Erdoğan."
    }
  ]
}

