      "date": "1877",
      "headline": "Discovery of Acetanilide",
      "text": "Acetanilide, the first aniline derivative with analgesic and antipyretic properties, was discovered. It was the precursor to the development of paracetamol."
    },
    {
      "date": "1887",
      "headline": "Synthesis of Paracetamol",
      "text": "Paracetamol was first synthesized by Harmon Northrop Morse at Johns Hopkins University by reducing p-nitrophenol with tin in glacial acetic acid."
    },
    {
      "date": "1893",
      "headline": "First Clinical Use",
      "text": "Paracetamol was first used clinically by Joseph von Mering, who noted its antipyretic properties."
    },
    {
      "date": "1948",
      "headline": "Rediscovery and Testing",
      "text": "Paracetamol was rediscovered as a metabolite of acetanilide and phenacetin, leading to further testing and recognition of its safety and efficacy."
    },
    {
      "date": "1955",
      "headline": "Introduction of Tylenol",
      "text": "Paracetamol was introduced to the market in the United States under the brand name Tylenol by McNeil Laboratories."
    },
    {
      "date": "1956",
      "headline": "Introduction of Panadol",
      "text": "Paracetamol was introduced in the United Kingdom under the brand name Panadol, initially available only by prescription."
    },
    {
      "date": "1970",
      "headline": "Over-the-Counter Availability",
      "text": "Paracetamol became available over-the-counter in many countries, increasing its accessibility and popularity as a pain reliever and fever reducer."
    },
    {
      "date": "1980s",
      "headline": "Widespread Use",
      "text": "Paracetamol became one of the most widely used over-the-counter medications worldwide for pain and fever relief."
    },
    {
      "date": "2009",
      "headline": "FDA Warning",
      "text": "The U.S. Food and Drug Administration issued a warning about the risk of severe liver damage associated with the use of paracetamol, particularly when taken in high doses or combined with alcohol."
    },
    {
      "date": "2011",
      "headline": "Dosage Recommendations Revised",
      "text": "The FDA revised the maximum recommended dosage of paracetamol to reduce the risk of liver damage, advising a maximum of 3,000 to 4,000 mg per day for adults."
    }
  ]
}

