    {
      "date": "-0168",
      "headline": "Antiochus IV Epiphanes' Persecution",
      "text": "Antiochus IV Epiphanes, a Hellenistic Greek king of the Seleucid Empire, outlawed Jewish religious practices and desecrated the Second Temple in Jerusalem, leading to the Maccabean Revolt."
    },
    {
      "date": "1096",
      "headline": "First Crusade Massacres",
      "text": "During the First Crusade, mobs of crusaders attacked Jewish communities in the Rhineland, resulting in massacres in cities such as Worms, Mainz, and Cologne."
    },
    {
      "date": "1215",
      "headline": "Fourth Lateran Council",
      "text": "The Fourth Lateran Council, convened by Pope Innocent III, imposed various restrictions on Jews, including the requirement to wear distinctive clothing."
    },
    {
      "date": "1290",
      "headline": "Expulsion from England",
      "text": "King Edward I issued the Edict of Expulsion, ordering the expulsion of all Jews from England. This edict remained in effect until the 17th century."
    },
    {
      "date": "1348",
      "headline": "Black Death Persecutions",
      "text": "Jews were scapegoated for the Black Death, leading to widespread violence and massacres against Jewish communities throughout Europe."
    },
    {
      "date": "1492",
      "headline": "Expulsion from Spain",
      "text": "The Alhambra Decree ordered the expulsion of practicing Jews from Spain, forcing them to convert to Christianity or leave the country."
    },
    {
      "date": "1543",
      "headline": "Martin Luther's 'On the Jews and Their Lies'",
      "text": "Martin Luther published 'On the Jews and Their Lies,' a treatise that called for harsh measures against Jews, including the destruction of synagogues and Jewish homes."
    },
    {
      "date": "1894",
      "headline": "Dreyfus Affair",
      "text": "The wrongful conviction of Jewish French army officer Alfred Dreyfus for treason highlighted deep-seated antisemitism in France and led to widespread public debate."
    },
    {
      "date": "1903",
      "headline": "Kishinev Pogrom",
      "text": "A violent pogrom against Jews occurred in Kishinev, then part of the Russian Empire, resulting in the deaths of 49 Jews and widespread destruction of property."
    },
    {
      "date": "1933",
      "headline": "Nazi Rise to Power",
      "text": "Adolf Hitler and the Nazi Party rose to power in Germany, implementing policies that institutionalized antisemitism and led to the Holocaust."
    },
    {
      "date": "1935",
      "headline": "Nuremberg Laws",
      "text": "The Nuremberg Laws were enacted in Nazi Germany, stripping Jews of German citizenship and prohibiting marriage or sexual relations between Jews and non-Jewish Germans."
    },
    {
      "date": "1941",
      "headline": "The Final Solution",
      "text": "Nazi Germany implemented the 'Final Solution,' a plan to systematically exterminate the Jewish population of Europe, resulting in the Holocaust."
    },
    {
      "date": "1945",
      "headline": "End of the Holocaust",
      "text": "The Holocaust ended with the defeat of Nazi Germany in World War II, having resulted in the deaths of approximately six million Jews."
    },
    {
      "date": "1965",
      "headline": "Nostra Aetate",
      "text": "The Second Vatican Council issued 'Nostra Aetate,' a declaration that repudiated antisemitism and called for improved relations between Catholics and Jews."
    },
