{
  "timeline": [
    {
      "date": "1930-02-18",
      "headline": "Discovery of Pluto",
      "text": "Pluto was discovered by astronomer Clyde Tombaugh at the Lowell Observatory in Flagstaff, Arizona. The discovery was the result of a systematic search for a ninth planet, initiated by Percival Lowell."
    },
    {
      "date": "1930-03-13",
      "headline": "Announcement of Pluto's Discovery",
      "text": "The discovery of Pluto was publicly announced by the Lowell Observatory. The date was chosen to coincide with the anniversary of the birth of Percival Lowell and the discovery of Uranus."
    },
    {
      "date": "1930-05-01",
      "headline": "Naming of Pluto",
      "text": "The name 'Pluto' was officially adopted for the newly discovered celestial body. The name was suggested by Venetia Burney, an 11-year-old schoolgirl from Oxford, England, and was chosen in part because it honored Percival Lowell, whose initials are the first two letters of Pluto."
    },
    {
      "date": "1978-06-22",
      "headline": "Discovery of Charon",
      "text": "Charon, the largest moon of Pluto, was discovered by astronomer James Christy at the United States Naval Observatory. This discovery provided a better understanding of Pluto's mass and size."
    },
    {
      "date": "2006-08-24",
      "headline": "Reclassification as a Dwarf Planet",
      "text": "The International Astronomical Union (IAU) redefined the criteria for planet classification, resulting in Pluto being reclassified as a 'dwarf planet.' This decision was based on the fact that Pluto had not cleared its neighboring region of other objects."
    },
    {
      "date": "2015-07-14",
      "headline": "New Horizons Flyby",
      "text": "NASA's New Horizons spacecraft conducted a flyby of Pluto, providing the first close-up images and detailed data about the dwarf planet and its moons. This mission significantly expanded our understanding of Pluto's geology and atmosphere."
    }
  ]
}

