{
  "timeline": [
    {
      "date": "-3000",
      "headline": "Early Use of Coca Leaves",
      "text": "Indigenous peoples in South America begin using coca leaves for their stimulant effects, chewing them for increased energy and reduced hunger."
    },
    {
      "date": "1859",
      "headline": "Isolation of Cocaine",
      "text": "German chemist Albert Niemann isolates cocaine from coca leaves, marking the first time the active alkaloid is extracted."
    },
    {
      "date": "1884",
      "headline": "Medical Use of Cocaine",
      "text": "Austrian ophthalmologist Carl Koller introduces cocaine as a local anesthetic in eye surgery, revolutionizing surgical procedures."
    },
    {
      "date": "1886",
      "headline": "Coca-Cola Formulation",
      "text": "John Stith Pemberton includes coca leaf extract in the original formulation of Coca-Cola, contributing to its early popularity."
    },
    {
      "date": "1904",
      "headline": "Removal from Coca-Cola",
      "text": "Coca-Cola removes cocaine from its formula, replacing it with decocainized coca leaf extract due to growing concerns about cocaine's addictive properties."
    },
    {
      "date": "1914",
      "headline": "Harrison Narcotics Tax Act",
      "text": "The United States passes the Harrison Narcotics Tax Act, regulating and taxing the production and distribution of cocaine and other narcotics."
    },
    {
      "date": "1970",
      "headline": "Controlled Substances Act",
      "text": "The United States classifies cocaine as a Schedule II drug under the Controlled Substances Act, recognizing its medical use but also its high potential for abuse."
    },
    {
      "date": "1980s",
      "headline": "Cocaine Epidemic",
      "text": "Cocaine use surges in the United States, leading to widespread addiction and social issues, often associated with the crack cocaine epidemic."
    },
    {
