{
  "timeline": [
    {
      "date": "1966-05",
      "headline": "Launch of the Cultural Revolution",
      "text": "Mao Zedong officially launched the Cultural Revolution in May 1966, aiming to preserve Chinese communism by purging remnants of capitalist and traditional elements from Chinese society."
    },
    {
      "date": "1966-08-08",
      "headline": "Sixteen Points Decision",
      "text": "The Central Committee of the Chinese Communist Party adopted the 'Decision Concerning the Great Proletarian Cultural Revolution,' also known as the Sixteen Points, which outlined the goals and methods of the Cultural Revolution."
    },
    {
      "date": "1966-08",
      "headline": "Red Guards Movement",
      "text": "Mao called on the youth to form Red Guards and attack the 'Four Olds': old customs, old culture, old habits, and old ideas. This led to widespread chaos and violence."
    },
    {
      "date": "1967-01",
      "headline": "January Storm",
      "text": "The 'January Storm' occurred when radical groups seized power from local governments in Shanghai, marking a significant escalation in the Cultural Revolution."
    },
    {
      "date": "1968-10",
      "headline": "Cleansing the Class Ranks Campaign",
      "text": "The campaign was launched to eliminate perceived enemies of the revolution, resulting in widespread persecution and deaths."
    },
    {
      "date": "1969-04",
      "headline": "Ninth Party Congress",
      "text": "The Ninth National Congress of the Chinese Communist Party was held, where Lin Biao was named Mao's successor, and the Cultural Revolution was declared a success."
    },
    {
      "date": "1971-09",
      "headline": "Lin Biao Incident",
      "text": "Lin Biao, Mao's designated successor, died in a plane crash while allegedly fleeing to the Soviet Union after a failed coup attempt."
    },
    {
      "date": "1972",
      "headline": "Normalization of Relations with the United States",
      "text": "China began to normalize relations with the United States, marked by President Richard Nixon's visit to China, signaling a shift in foreign policy amidst the Cultural Revolution."
    },
    {
      "date": "1976-01",
      "headline": "Death of Zhou Enlai",
      "text": "Premier Zhou Enlai, a key figure in the Chinese government, died, leading to public mourning and political tension."
    },
    {
      "date": "1976-09-09",
      "headline": "Death of Mao Zedong",
      "text": "Mao Zedong died, marking the end of the Cultural Revolution. His death led to a power struggle and eventual reforms in China."
    },
    {
      "date": "1976-10",
      "headline": "Arrest of the Gang of Four",
      "text": "The Gang of Four, a political faction associated with the Cultural Revolution, was arrested, effectively ending the movement and paving the way for China's reform era."
    }
  ]
}

