{
  "timeline": [
    {
      "date": "1582-02-24",
      "headline": "Papal Bull Issued",
      "text": "Pope Gregory XIII issued the papal bull 'Inter gravissimas', which outlined the reform of the Julian calendar and introduced the Gregorian calendar."
    },
    {
      "date": "1582-10-04",
      "headline": "Last Day of Julian Calendar",
      "text": "The last day of the Julian calendar was observed in countries that adopted the Gregorian calendar immediately, including Italy, Poland, Portugal, and Spain."
    },
    {
      "date": "1582-10-15",
      "headline": "First Day of Gregorian Calendar",
      "text": "The Gregorian calendar was implemented, skipping 10 days to realign the calendar with the equinoxes. October 15, 1582, followed October 4, 1582."
    },
    {
      "date": "1583",
      "headline": "Adoption by Catholic Countries",
      "text": "The Gregorian calendar was gradually adopted by other Catholic countries, including France and the Catholic states of the Holy Roman Empire."
    },
    {
      "date": "1700",
      "headline": "Adoption by Protestant Germany and Netherlands",
      "text": "Protestant regions of Germany and the Netherlands adopted the Gregorian calendar."
    },
    {
      "date": "1752",
      "headline": "Adoption by Great Britain and Colonies",
      "text": "Great Britain and its American colonies adopted the Gregorian calendar, skipping 11 days in September 1752."
    },
    {
      "date": "1918",
      "headline": "Adoption by Soviet Russia",
      "text": "Soviet Russia adopted the Gregorian calendar, replacing the Julian calendar."
    },
    {
      "date": "1923",
      "headline": "Adoption by Greece",
      "text": "Greece became the last European country to adopt the Gregorian calendar."
    }
  ]
}

{
  "timeline": [
    {
      "date": "1525",
      "headline": "Secularization of Prussia",
      "text": "The Prussian part of the State of the Teutonic Order was secularized, marking the beginning of the Duchy of Prussia. Albert of Brandenburg-Ansbach, the last Grand Master of the Teutonic Knights, became the first Duke of Prussia."
    },
    {
      "date": "1618",
      "headline": "Union with Brandenburg",
      "text": "The Duchy of Prussia was inherited by the Elector of Brandenburg, John Sigismund, creating a personal union between Brandenburg and Prussia."
    },
    {
      "date": "1701",
      "headline": "Kingdom of Prussia Established",
      "text": "Frederick I crowned himself King in Prussia, elevating the status of the duchy to a kingdom. This marked the beginning of the Kingdom of Prussia."
    },
    {
      "date": "1740",
      "headline": "Frederick the Great's Reign Begins",
      "text": "Frederick II, known as Frederick the Great, ascended to the throne. His reign marked a period of military expansion and cultural development."
    },
    {
      "date": "1740-1748",
      "headline": "War of Austrian Succession",
      "text": "Prussia, under Frederick the Great, participated in the War of Austrian Succession, gaining the region of Silesia."
    },
    {
      "date": "1756-1763",
      "headline": "Seven Years' War",
      "text": "Prussia fought in the Seven Years' War, emerging as a major European power despite being heavily outnumbered by its enemies."
    },
    {
      "date": "1806",
      "headline": "Defeat by Napoleon",
      "text": "Prussia was defeated by Napoleon at the Battle of Jena-Auerstedt, leading to significant territorial losses and reforms."
    },
    {
      "date": "1815",
      "headline": "Congress of Vienna",
      "text": "Prussia gained significant territories, including parts of Saxony and the Rhineland, at the Congress of Vienna, strengthening its position in Europe."
    },
    {
      "date": "1866",
      "headline": "Austro-Prussian War",
      "text": "Prussia defeated Austria in the Austro-Prussian War, leading to the exclusion of Austria from German affairs and the establishment of the North German Confederation."
    },
    {
      "date": "1871",
      "headline": "German Empire Proclaimed",
      "text": "The German Empire was proclaimed in the Hall of Mirrors at the Palace of Versailles, with the King of Prussia, Wilhelm I, becoming the German Emperor."
    },
    {
      "date": "1918",
      "headline": "End of the German Monarchy",
      "text": "The German monarchy was abolished following Germany's defeat in World War I, leading to the abdication of Wilhelm II and the end of the Kingdom of Prussia."
    },
    {
      "date": "1947",
      "headline": "Formal Abolition of Prussia",
      "text": "Prussia was formally abolished by the Allied Control Council, marking the end of Prussia as a political entity."
    }
  ]
}

