{
  "timeline": [
    {
      "date": "1119",
      "headline": "Foundation of the Knights Templar",
      "text": "The Knights Templar was founded around 1119 by a small group of knights led by Hugues de Payens. The order was established to protect Christian pilgrims traveling to the Holy Land following the First Crusade."
    },
    {
      "date": "1129",
      "headline": "Council of Troyes",
      "text": "The Knights Templar received formal endorsement from the Catholic Church at the Council of Troyes. This endorsement helped the order gain support and resources, allowing it to expand its influence and operations."
    },
    {
      "date": "1139",
      "headline": "Papal Bull Omne Datum Optimum",
      "text": "Pope Innocent II issued the papal bull Omne Datum Optimum, which granted the Knights Templar special privileges, including exemption from local laws and taxes, and the ability to collect their own tithes."
    },
    {
      "date": "1147",
      "headline": "Second Crusade",
      "text": "The Knights Templar played a significant role in the Second Crusade, providing military support and protection for Christian territories in the Holy Land."
    },
    {
      "date": "1187",
      "headline": "Battle of Hattin",
      "text": "The Knights Templar suffered a major defeat at the Battle of Hattin against the forces of Saladin, leading to the loss of Jerusalem and a significant decline in their influence in the Holy Land."
    },
    {
      "date": "1191",
      "headline": "Siege of Acre",
      "text": "The Knights Templar participated in the Siege of Acre during the Third Crusade, helping to recapture the city from Muslim forces."
    },
    {
      "date": "1291",
      "headline": "Fall of Acre",
      "text": "The fall of Acre marked the end of Christian control in the Holy Land. The Knights Templar, along with other Christian forces, were forced to retreat to Cyprus."
    },
    {
      "date": "1307-10-13",
      "headline": "Arrest of the Knights Templar",
      "text": "On Friday, October 13, 1307, King Philip IV of France ordered the arrest of the Knights Templar. Many members were charged with heresy and other crimes, leading to the order's downfall."
    },
    {
      "date": "1312",
      "headline": "Dissolution of the Knights Templar",
      "text": "Pope Clement V officially dissolved the Knights Templar at the Council of Vienne, following pressure from King Philip IV of France."
    },
    {
      "date": "1314-03-18",
      "headline": "Execution of Jacques de Molay",
      "text": "Jacques de Molay, the last Grand Master of the Knights Templar, was executed by burning at the stake in Paris, marking the end of the order's leadership."
    }
  ]
}

