{
  "timeline": [
    {
      "date": "1915-04-24",
      "headline": "Arrest of Armenian Intellectuals",
      "text": "On April 24, 1915, the Ottoman government arrested and deported hundreds of Armenian intellectuals and community leaders from Constantinople (modern-day Istanbul), marking the beginning of the Armenian Genocide."
    },
    {
      "date": "1915-05-27",
      "headline": "Tehcir Law Enacted",
      "text": "The Ottoman Parliament passed the Temporary Law of Deportation, also known as the Tehcir Law, which authorized the deportation of Armenians from their homes, ostensibly for security reasons."
    },
    {
      "date": "1915-06",
      "headline": "Mass Deportations Begin",
      "text": "Mass deportations of Armenians began in earnest, with hundreds of thousands of Armenians forced to march to the Syrian Desert. Many died from starvation, dehydration, and exhaustion along the way."
    },
    {
      "date": "1915-08",
      "headline": "Massacres in Anatolia",
      "text": "Throughout the summer of 1915, systematic massacres of Armenians occurred across Anatolia, with entire villages and towns being wiped out."
    },
    {
      "date": "1916",
      "headline": "Continued Massacres and Deportations",
      "text": "The genocide continued into 1916, with further massacres and deportations. Many Armenians who survived the initial deportations were killed in concentration camps in the Syrian Desert."
    },
    {
      "date": "1918",
      "headline": "End of World War I",
      "text": "With the end of World War I, the Ottoman Empire collapsed, and the genocide effectively came to an end. However, the aftermath left the Armenian population decimated and scattered."
    },
    {
      "date": "1919",
      "headline": "Turkish Courts-Martial",
      "text": "In 1919, the Ottoman government held courts-martial for some of the leaders responsible for the genocide, resulting in several death sentences. However, these were largely symbolic and not enforced."
    },
    {
      "date": "1923",
      "headline": "Treaty of Lausanne",
      "text": "The Treaty of Lausanne was signed, establishing the borders of modern Turkey and effectively ending any international efforts to hold the Ottoman Empire accountable for the genocide."
    }
  ]
}

