{
  "timeline": [
    {
      "date": "0001",
      "headline": "Emergence of Gnostic Ideas",
      "text": "Gnostic ideas began to emerge in the late 1st century AD among Jewish and early Christian sects, emphasizing personal spiritual knowledge (gnosis) over orthodox teachings."
    },
    {
      "date": "0140",
      "headline": "Valentinus' Teachings",
      "text": "Valentinus, a prominent Gnostic teacher, began spreading his teachings in Rome around 140 AD, significantly influencing Gnostic thought with his complex cosmology and theology."
    },
    {
      "date": "0180",
      "headline": "Irenaeus' 'Against Heresies'",
      "text": "Irenaeus, a Church Father, wrote 'Against Heresies' around 180 AD, a critical work that aimed to refute Gnostic beliefs and defend orthodox Christianity."
    },
    {
      "date": "0194",
      "headline": "Clement of Alexandria's Writings",
      "text": "Clement of Alexandria, an early Christian theologian, wrote extensively against Gnosticism around 194 AD, incorporating some Gnostic ideas into his own teachings."
    },
    {
      "date": "0250",
      "headline": "Manichaeism Emerges",
      "text": "Manichaeism, a syncretic religion with Gnostic elements, was founded by the prophet Mani around 250 AD, spreading rapidly across the Roman Empire and beyond."
    },
    {
      "date": "0325",
      "headline": "Council of Nicaea",
      "text": "The First Council of Nicaea in 325 AD marked a significant moment in the establishment of orthodox Christian doctrine, further marginalizing Gnostic beliefs."
    },
    {
      "date": "0380",
      "headline": "Theodosian Decrees",
      "text": "Theodosius I issued decrees in 380 AD that made Nicene Christianity the state religion of the Roman Empire, leading to increased persecution of Gnostic sects."
    },
    {
      "date": "1945",
      "headline": "Nag Hammadi Library Discovery",
      "text": "In 1945, a collection of Gnostic texts, known as the Nag Hammadi library, was discovered in Egypt, providing significant insights into Gnostic beliefs and practices."
    }
  ]
}

