    },
    {
      "date": "1972-09-05",
      "headline": "Failed Rescue Attempt",
      "text": "A failed rescue attempt was made by German police at the Fürstenfeldbruck airbase, where the hostages and terrorists were taken. The operation resulted in the deaths of all nine hostages, five of the terrorists, and one German police officer."
    },
    {
      "date": "1972-09-06",
      "headline": "Aftermath and Reactions",
      "text": "The Munich massacre led to widespread international condemnation and increased security measures at future Olympic Games. The Israeli government launched Operation Wrath of God to track down and eliminate those responsible for the attack."
    }
  ]
}

