{
  "timeline": [
    {
      "date": "-0027",
      "headline": "Original Pantheon Commissioned",
      "text": "The original Pantheon was commissioned by Marcus Vipsanius Agrippa during the reign of Augustus. It was intended as a temple to all the gods of ancient Rome."
    },
    {
      "date": "0080",
      "headline": "Pantheon Destroyed by Fire",
      "text": "The original Pantheon was destroyed by a fire in 80 AD, which was part of a larger fire that swept through Rome."
    },
    {
      "date": "0110",
      "headline": "Reconstruction by Domitian",
      "text": "The Pantheon was rebuilt by Emperor Domitian after the fire, but it was struck by lightning and burned again in 110 AD."
    },
    {
      "date": "0126",
      "headline": "Current Pantheon Completed",
      "text": "The current Pantheon was completed under the reign of Emperor Hadrian, who chose to retain the original inscription attributing the building to Agrippa."
    },
    {
      "date": "0609",
      "headline": "Pantheon Converted to a Christian Church",
      "text": "The Pantheon was consecrated as a Christian church by Pope Boniface IV, dedicated to St. Mary and the Martyrs, which helped ensure its preservation."
    },
    {
      "date": "1632",
      "headline": "Bronze Ceiling Removed",
      "text": "Pope Urban VIII ordered the removal of the bronze ceiling from the portico of the Pantheon, which was used to make cannons for the Castel Sant'Angelo."
    },
    {
      "date": "1870",
      "headline": "Pantheon Becomes a National Mausoleum",
      "text": "The Pantheon was designated as a national mausoleum for Italian kings, and it houses the tombs of several Italian monarchs, including Victor Emmanuel II."
    }
  ]
}

