{
  "timeline": [
    {
      "date": "-3100",
      "headline": "Unification of Upper and Lower Egypt",
      "text": "The political unification of Upper and Lower Egypt under the first pharaoh, traditionally identified as Menes, marked the beginning of the Early Dynastic Period and the start of ancient Egyptian civilization."
    },
    {
      "date": "-2686",
      "headline": "Start of the Old Kingdom",
      "text": "The Old Kingdom period began, characterized by the construction of the first pyramids and the establishment of a centralized state."
    },
    {
      "date": "-2613",
      "headline": "Reign of Pharaoh Sneferu",
      "text": "Sneferu, the first pharaoh of the Fourth Dynasty, is known for building three pyramids, including the Bent Pyramid and the Red Pyramid."
    },
    {
      "date": "-2589",
      "headline": "Reign of Pharaoh Khufu",
      "text": "Khufu, also known as Cheops, ruled during the Fourth Dynasty and is best known for commissioning the Great Pyramid of Giza."
    },
    {
      "date": "-2181",
      "headline": "First Intermediate Period",
      "text": "A period of political fragmentation and chaos following the collapse of the Old Kingdom, lasting until the rise of the Middle Kingdom."
    },
    {
      "date": "-2055",
      "headline": "Start of the Middle Kingdom",
      "text": "The Middle Kingdom began with the reunification of Egypt under Pharaoh Mentuhotep II, marking a period of stability and prosperity."
    },
    {
      "date": "-1991",
      "headline": "Reign of Pharaoh Amenemhat I",
      "text": "Amenemhat I founded the Twelfth Dynasty and moved the capital to Itjtawy, initiating a period of economic and cultural renaissance."
    },
    {
      "date": "-1782",
      "headline": "Second Intermediate Period",
      "text": "A time of disunity and foreign rule, including the Hyksos invasion, which lasted until the establishment of the New Kingdom."
    },
    {
      "date": "-1550",
      "headline": "Start of the New Kingdom",
      "text": "The New Kingdom began with the expulsion of the Hyksos and the reunification of Egypt under Pharaoh Ahmose I."
    },
    {
      "date": "-1479",
      "headline": "Reign of Pharaoh Hatshepsut",
      "text": "Hatshepsut, one of the few female pharaohs, ruled as a regent and later as pharaoh, known for her prosperous reign and extensive building projects."
    },
    {
      "date": "-1353",
      "headline": "Reign of Pharaoh Akhenaten",
      "text": "Akhenaten is known for his religious revolution, promoting the worship of Aten and establishing a new capital at Amarna."
    },
    {
      "date": "-1332",
      "headline": "Reign of Pharaoh Tutankhamun",
      "text": "Tutankhamun, also known as King Tut, is famous for his intact tomb discovered in the Valley of the Kings."
    },
    {
      "date": "-1279",
      "headline": "Reign of Pharaoh Ramesses II",
      "text": "Ramesses II, also known as Ramesses the Great, is remembered for his military campaigns, extensive building projects, and the signing of the first known peace treaty."
    },
    {
      "date": "-1070",
      "headline": "Third Intermediate Period",
      "text": "A period of political instability and division following the decline of the New Kingdom, characterized by the rule of Libyan and Nubian dynasties."
    },
    {
      "date": "-664",
      "headline": "Late Period",
      "text": "The Late Period began with the reunification of Egypt under the Twenty-sixth Dynasty, also known as the Saite Dynasty."
    },
    {
      "date": "-525",
      "headline": "Persian Conquest",
      "text": "Egypt was conquered by the Persian Empire, marking the beginning of the First Persian Period."
    },
    {
      "date": "-332",
      "headline": "Conquest by Alexander the Great",
      "text": "Alexander the Great conquered Egypt, ending Persian rule and beginning the Hellenistic period under the Ptolemaic Dynasty."
    },
    {
      "date": "-30",
      "headline": "End of Ancient Egyptian Civilization",
      "text": "The death of Cleopatra VII and the Roman annexation of Egypt marked the end of ancient Egyptian civilization and the beginning of Roman rule."
    }
  ]
}

