{
  "timeline": [
    {
      "date": "2009-01-15",
      "headline": "Flight 1549 Takes Off",
      "text": "US Airways Flight 1549, an Airbus A320, took off from LaGuardia Airport in New York City, bound for Charlotte Douglas International Airport in North Carolina."
    },
    {
      "date": "2009-01-15",
      "headline": "Bird Strike",
      "text": "Shortly after takeoff, the aircraft struck a flock of Canada geese at an altitude of approximately 2,818 feet, causing both engines to lose power."
    },
    {
      "date": "2009-01-15",
      "headline": "Decision to Ditch",
      "text": "Captain Chesley 'Sully' Sullenberger and First Officer Jeffrey Skiles assessed their options and decided to ditch the aircraft in the Hudson River due to insufficient altitude and power to reach a nearby airport."
    },
    {
      "date": "2009-01-15",
      "headline": "Ditching in the Hudson River",
      "text": "At approximately 3:31 PM, the aircraft successfully ditched in the Hudson River near Midtown Manhattan. The ditching was executed with remarkable precision, and the plane remained largely intact."
    },
    {
      "date": "2009-01-15",
      "headline": "Rescue Operations",
      "text": "All 155 passengers and crew were safely evacuated from the aircraft. Nearby boats, including commuter ferries, quickly arrived at the scene to assist in the rescue operations."
    },
    {
      "date": "2009-01-15",
      "headline": "No Fatalities",
      "text": "Remarkably, there were no fatalities among the passengers and crew. However, 100 people sustained injuries, with some being serious."
    },
    {
      "date": "2009-01-15",
      "headline": "Investigation Begins",
      "text": "The National Transportation Safety Board (NTSB) began an investigation into the incident, focusing on the bird strike and the subsequent loss of engine power."
    },
    {
      "date": "2009-06-09",
      "headline": "NTSB Hearing",
      "text": "The NTSB held a public hearing to discuss the incident, where they praised the actions of the flight crew and the successful ditching of the aircraft."
    },
    {
      "date": "2010-05-04",
      "headline": "NTSB Final Report",
      "text": "The NTSB released its final report, concluding that the ditching was a result of the bird strike and loss of engine power, and commended the flight crew for their skillful handling of the emergency."
    }
  ]
}

