    },
    {
      "date": "1815",
      "headline": "Congress of Vienna",
      "text": "The Congress of Vienna recognized San Marino's independence, further solidifying its status as a sovereign state in post-Napoleonic Europe."
    },
    {
      "date": "1862",
      "headline": "Treaty with Italy",
      "text": "San Marino signed a treaty of friendship and cooperation with the newly unified Kingdom of Italy, ensuring its independence and neutrality."
    },
    {
      "date": "1944",
      "headline": "World War II Neutrality",
      "text": "San Marino maintained its neutrality during World War II, although it was briefly occupied by German forces in 1944 before being liberated by the Allies."
    },
    {
      "date": "1992",
      "headline": "United Nations Membership",
