{
  "timeline": [
    {
      "date": "0610",
      "headline": "First Revelation",
      "text": "According to Islamic tradition, the first revelation of the Quran was received by the Prophet Muhammad in the Cave of Hira during the month of Ramadan in 610 CE. The angel Gabriel is said to have delivered the message from God."
    },
    {
      "date": "0610-0632",
      "headline": "Revelation Period",
      "text": "The Quran was revealed to the Prophet Muhammad over a period of approximately 22 years, from 610 CE until his death in 632 CE. The revelations were received in various circumstances and locations."
    },
    {
      "date": "0632",
      "headline": "Compilation Begins",
      "text": "After the death of the Prophet Muhammad, the Quran was compiled into a single book. The first caliph, Abu Bakr, initiated this process due to concerns about preserving the revelations after many who had memorized them died in battle."
    },
    {
      "date": "0650",
      "headline": "Standardization Under Uthman",
      "text": "The third caliph, Uthman ibn Affan, ordered the standardization of the Quran around 650 CE. He commissioned a committee to produce a single, authoritative text and distributed copies to various Islamic regions to prevent discrepancies."
    },
    {
      "date": "0700",
      "headline": "Development of Quranic Exegesis",
      "text": "By the 8th century, the study and interpretation of the Quran, known as Tafsir, began to develop as a formal discipline. Scholars sought to explain the meanings and contexts of the verses."
    },
    {
      "date": "0800",
      "headline": "Emergence of Quranic Sciences",
      "text": "By the 9th century, various sciences related to the Quran, such as Tajwid (the art of recitation) and Qira'at (the study of different readings), began to emerge, further enriching Islamic scholarship."
    },
    {
      "date": "1924",
      "headline": "Cairo Edition",
      "text": "In 1924, the Al-Azhar University in Cairo published a standardized edition of the Quran, which became widely accepted and used in the Muslim world. This edition helped unify the text for educational and religious purposes."
    }
  ]
}

