{
  "timeline": [
    {
      "date": "1863-07-30",
      "headline": "Birth of Henry Ford",
      "text": "Henry Ford was born on July 30, 1863, on a farm in Greenfield Township, Michigan, which is now part of Dearborn."
    },
    {
      "date": "1879",
      "headline": "Apprenticeship at James F. Flower & Bros.",
      "text": "At the age of 16, Henry Ford left home to work as an apprentice machinist in Detroit, first with James F. Flower & Bros., and later with the Detroit Dry Dock Company."
    },
    {
      "date": "1891",
      "headline": "Chief Engineer at Edison Illuminating Company",
      "text": "Henry Ford became an engineer with the Edison Illuminating Company of Detroit. This position gave him the time and money to devote attention to his personal experiments on gasoline engines."
    },
    {
      "date": "1896",
      "headline": "Completion of the Quadricycle",
      "text": "Henry Ford completed his first self-propelled vehicle, the Ford Quadricycle, which was a simple frame with four bicycle wheels and a four-horsepower engine."
    },
    {
      "date": "1903-06-16",
      "headline": "Founding of Ford Motor Company",
      "text": "Henry Ford and 11 associate investors founded the Ford Motor Company, marking the start of one of the most successful automobile companies in history."
    },
    {
      "date": "1908",
      "headline": "Introduction of the Model T",
      "text": "Ford introduced the Model T, a car that was affordable, versatile, and easy to maintain, which became extremely popular and revolutionized the automobile industry."
    },
    {
      "date": "1913",
      "headline": "Implementation of the Moving Assembly Line",
      "text": "Henry Ford introduced the moving assembly line to automobile production, significantly reducing the time it took to build a car and lowering costs."
    },
    {
      "date": "1914",
      "headline": "Five-Dollar Workday",
      "text": "Ford announced a $5 per day wage for his workers, which was more than double the average wage at the time, improving worker satisfaction and reducing turnover."
    },
    {
      "date": "1918",
      "headline": "Ford's Attempt to Enter Politics",
      "text": "Henry Ford ran for the U.S. Senate as a Democrat from Michigan, encouraged by President Woodrow Wilson, but was narrowly defeated."
    },
    {
      "date": "1926",
      "headline": "Introduction of the Five-Day Workweek",
      "text": "Ford Motor Company became one of the first companies in America to adopt a five-day, 40-hour workweek for its workers."
    },
    {
      "date": "1941",
      "headline": "Ford Motor Company and World War II",
      "text": "Ford Motor Company began producing B-24 Liberator bombers for the war effort, contributing significantly to the Allied powers during World War II."
    },
    {
      "date": "1947-04-07",
      "headline": "Death of Henry Ford",
      "text": "Henry Ford passed away at the age of 83 in Dearborn, Michigan, leaving behind a legacy as a pioneer of the automotive industry and modern industrial practices."
    }
  ]
}

