    {
      "date": "0500",
      "headline": "Frankish Influence",
      "text": "The Frankish tribes invaded Gaul, introducing Germanic elements into the Vulgar Latin spoken there, contributing to the development of Old French."
    },
    {
      "date": "0842",
      "headline": "Oaths of Strasbourg",
      "text": "The Oaths of Strasbourg were sworn in a Romance language that was a precursor to Old French, marking one of the earliest known examples of the language."
    },
    {
      "date": "0843",
      "headline": "Treaty of Verdun",
      "text": "The Treaty of Verdun divided the Carolingian Empire, leading to the development of distinct Romance languages, including French, in the western part."
    },
    {
      "date": "1100",
      "headline": "Development of Old French",
      "text": "Old French began to emerge as a distinct language, with various dialects spoken across northern France."
    },
    {
      "date": "1539",
      "headline": "Ordinance of Villers-Cotterêts",
      "text": "King Francis I of France issued the Ordinance of Villers-Cotterêts, making French the official language of legal documents in France, promoting its use over Latin."
    },
    {
      "date": "1635",
      "headline": "Founding of the Académie Française",
      "text": "Cardinal Richelieu established the Académie Française to standardize and preserve the French language."
    },
    {
      "date": "1789",
      "headline": "French Revolution",
      "text": "The French Revolution promoted the use of French as a national language, diminishing the use of regional languages and dialects."
    },
    {
      "date": "1880",
      "headline": "French Colonial Expansion",
      "text": "French colonial expansion spread the French language to Africa, Southeast Asia, and the Caribbean, leading to the development of French-based creole languages."
    },
    {
      "date": "1970",
      "headline": "Francophonie Organization Established",
      "text": "The Organisation internationale de la Francophonie was established to promote the French language and cultural and linguistic diversity."
    }
  ]
}

