    {
      "date": "1955-08-28",
      "headline": "Abduction and Murder",
      "text": "Emmett Till was abducted from his great-uncle's home by Roy Bryant and J.W. Milam. He was brutally beaten, shot, and his body was thrown into the Tallahatchie River."
    },
    {
      "date": "1955-08-31",
      "headline": "Body Discovered",
      "text": "Emmett Till's mutilated body was discovered in the Tallahatchie River. He was identified by a ring he was wearing, which belonged to his father."
    },
    {
      "date": "1955-09-03",
      "headline": "Funeral and Open Casket",
      "text": "Emmett Till's funeral was held in Chicago. His mother, Mamie Till, insisted on an open casket to show the world the brutality of his murder."
    },
    {
      "date": "1955-09-19",
      "headline": "Trial of Roy Bryant and J.W. Milam",
      "text": "The trial of Roy Bryant and J.W. Milam began in Sumner, Mississippi. The all-white, all-male jury acquitted them of Emmett Till's murder after a brief deliberation."
    },
    {
      "date": "1956-01",
      "headline": "Confession to Look Magazine",
      "text": "Roy Bryant and J.W. Milam confessed to the murder of Emmett Till in an interview with Look magazine, protected from further prosecution by double jeopardy."
    },
    {
      "date": "2008",
      "headline": "Carolyn Bryant Recantation",
      "text": "In a 2008 interview, Carolyn Bryant admitted that she had fabricated parts of her testimony regarding Emmett Till's actions."
