{
  "timeline": [
    {
      "date": "1900",
      "headline": "Planck's Quantum Hypothesis",
      "text": "Max Planck introduces the concept of quantization of energy, proposing that energy is emitted in discrete units called quanta. This marks the birth of quantum theory."
    },
    {
      "date": "1905",
      "headline": "Einstein's Photoelectric Effect",
      "text": "Albert Einstein explains the photoelectric effect by proposing that light consists of particles called photons, each carrying a quantum of energy. This work supports the quantum theory and earns him the Nobel Prize in Physics in 1921."
    },
    {
      "date": "1913",
      "headline": "Bohr Model of the Atom",
      "text": "Niels Bohr introduces a model of the atom where electrons orbit the nucleus in quantized energy levels, explaining the spectral lines of hydrogen."
    },
    {
      "date": "1924",
      "headline": "de Broglie's Matter Waves",
      "text": "Louis de Broglie proposes that particles, like electrons, have wave-like properties, introducing the concept of matter waves."
    },
    {
      "date": "1925",
      "headline": "Heisenberg's Matrix Mechanics",
      "text": "Werner Heisenberg develops matrix mechanics, the first complete formulation of quantum mechanics, which describes the behavior of quantum systems using matrices."
    },
    {
      "date": "1926",
      "headline": "Schrödinger's Wave Mechanics",
      "text": "Erwin Schrödinger formulates wave mechanics, introducing the Schrödinger equation, which describes how the quantum state of a physical system changes over time."
    },
    {
      "date": "1927",
      "headline": "Heisenberg Uncertainty Principle",
      "text": "Werner Heisenberg formulates the uncertainty principle, stating that certain pairs of physical properties, like position and momentum, cannot be simultaneously known to arbitrary precision."
    },
    {
      "date": "1927",
      "headline": "Copenhagen Interpretation",
      "text": "Niels Bohr and Werner Heisenberg develop the Copenhagen interpretation of quantum mechanics, which posits that physical systems generally do not have definite properties prior to being measured."
    },
    {
      "date": "1932",
      "headline": "Dirac's Quantum Field Theory",
      "text": "Paul Dirac develops quantum field theory, which combines quantum mechanics with special relativity and introduces the concept of antimatter."
    },
    {
      "date": "1935",
      "headline": "EPR Paradox",
      "text": "Albert Einstein, Boris Podolsky, and Nathan Rosen publish a paper highlighting what they see as a paradox in quantum mechanics, questioning the completeness of the theory and introducing the concept of 'spooky action at a distance.'"
    },
    {
      "date": "1947",
      "headline": "Development of Quantum Electrodynamics",
      "text": "Richard Feynman, Julian Schwinger, and Sin-Itiro Tomonaga develop quantum electrodynamics (QED), a quantum field theory of the electromagnetic force, which accurately describes how light and matter interact."
    },
    {
      "date": "1964",
      "headline": "Bell's Theorem",
      "text": "John Bell formulates Bell's theorem, which shows that certain predictions of quantum mechanics are incompatible with local hidden variable theories, supporting the non-locality of quantum mechanics."
    },
    {
      "date": "1982",
      "headline": "Aspect's Experiment",
      "text": "Alain Aspect and his team conduct experiments that confirm the predictions of quantum mechanics and the violation of Bell's inequalities, providing strong evidence against local hidden variable theories."
    },
    {
      "date": "1995",
      "headline": "First Bose-Einstein Condensate",
      "text": "Eric Cornell and Carl Wieman create the first Bose-Einstein condensate, a new state of matter predicted by Satyendra Nath Bose and Albert Einstein, demonstrating macroscopic quantum phenomena."
    }
  ]
}

