{
  "timeline": [
    {
      "date": "1703-05-27",
      "headline": "Founding of Saint Petersburg",
      "text": "Saint Petersburg was founded by Tsar Peter the Great on May 27, 1703. It was established on the site of the Swedish fortress Nyenschantz, which was captured by Russia during the Great Northern War."
    },
    {
      "date": "1712",
      "headline": "Capital of Russia",
      "text": "Saint Petersburg became the capital of Russia in 1712, replacing Moscow. It remained the capital until 1918."
    },
    {
      "date": "1725",
      "headline": "Peter the Great's Death",
      "text": "Peter the Great, the founder of Saint Petersburg, died in 1725. His death marked the end of an era of significant reforms and expansion for Russia."
    },
    {
      "date": "1825-12-14",
      "headline": "Decembrist Revolt",
      "text": "The Decembrist Revolt took place in Saint Petersburg on December 14, 1825, when Russian army officers led about 3,000 soldiers in protest against Tsar Nicholas I's assumption of the throne."
    },
    {
      "date": "1861",
      "headline": "Emancipation Reform",
      "text": "The Emancipation Reform of 1861, which freed the serfs in Russia, had significant social and economic impacts on Saint Petersburg, as it was a major center of industry and culture."
    },
    {
      "date": "1914",
      "headline": "Renamed Petrograd",
      "text": "During World War I, in 1914, Saint Petersburg was renamed Petrograd to sound less German."
    },
    {
      "date": "1917",
      "headline": "Russian Revolution",
      "text": "The Russian Revolution of 1917 began in Petrograd, leading to the abdication of Tsar Nicholas II and the eventual rise of the Soviet Union."
    },
    {
      "date": "1924",
      "headline": "Renamed Leningrad",
      "text": "Following the death of Vladimir Lenin in 1924, Petrograd was renamed Leningrad in his honor."
    },
    {
      "date": "1941-09-08",
      "headline": "Siege of Leningrad",
      "text": "The Siege of Leningrad began on September 8, 1941, during World War II. It lasted for 872 days, resulting in severe famine and casualties."
    },
    {
      "date": "1944-01-27",
      "headline": "End of Siege of Leningrad",
      "text": "The siege was lifted on January 27, 1944, marking a significant turning point in the Eastern Front of World War II."
    },
    {
      "date": "1991",
      "headline": "Renamed Saint Petersburg",
      "text": "Following the collapse of the Soviet Union, a referendum was held in 1991, and the city's name was changed back to Saint Petersburg."
    },
    {
      "date": "2003",
      "headline": "300th Anniversary",
      "text": "Saint Petersburg celebrated its 300th anniversary in 2003, marking three centuries since its founding by Peter the Great."
    }
  ]
}

{
  "timeline": [
    {
      "date": "1950",
      "headline": "Research on Adrenochrome Begins",
      "text": "In the 1950s, researchers began studying adrenochrome as a potential cause of schizophrenia. This period marked the start of limited scientific exploration into the compound's effects on mental health."
    },
    {
      "date": "1954",
      "headline": "Hoffer and Osmond's Hypothesis",
      "text": "Psychiatrists Abram Hoffer and Humphry Osmond proposed that adrenochrome might be a neurotoxic, psychotomimetic substance and could be responsible for some symptoms of schizophrenia."
    },
    {
      "date": "1960s",
      "headline": "Continued Research",
      "text": "Throughout the 1960s, research continued into the effects of adrenochrome, although it remained limited and inconclusive. The compound was studied for its potential psychotropic effects."
    },
    {
      "date": "1970s",
      "headline": "Decline in Research Interest",
      "text": "By the 1970s, interest in adrenochrome as a cause of schizophrenia had largely declined. The scientific community moved away from this line of inquiry due to lack of substantial evidence."
    },
    {
      "date": "Present",
      "headline": "Current Status",
      "text": "Adrenochrome has no current medical application. However, its semicarbazide derivative, carbazochrome, is used as a hemostatic medication."
    }
  ]
}

