      "date": "1869",
      "headline": "First Description",
      "text": "ALS was first described by French neurologist Jean-Martin Charcot in 1869. He identified the disease as a distinct neurological disorder characterized by the degeneration of motor neurons."
    },
    {
      "date": "1939",
      "headline": "Lou Gehrig Diagnosis",
      "text": "The disease gained significant public attention when famous American baseball player Lou Gehrig was diagnosed with ALS in 1939. His diagnosis brought widespread awareness to the condition in the United States."
    },
    {
      "date": "1993",
      "headline": "Discovery of SOD1 Gene Mutation",
      "text": "In 1993, scientists discovered that mutations in the SOD1 gene were linked to some cases of familial ALS, marking a significant breakthrough in understanding the genetic basis of the disease."
    },
    {
      "date": "1995",
      "headline": "FDA Approval of Riluzole",
      "text": "Riluzole became the first drug approved by the U.S. Food and Drug Administration (FDA) for the treatment of ALS in 1995. It was shown to modestly extend survival and delay the need for ventilator support."
    },
    {
      "date": "2014",
      "headline": "ALS Ice Bucket Challenge",
      "text": "The ALS Ice Bucket Challenge went viral on social media in 2014, raising over $115 million for ALS research and significantly increasing public awareness of the disease."
    },
    {
      "date": "2017",
      "headline": "FDA Approval of Edaravone",
      "text": "In 2017, the FDA approved Edaravone for the treatment of ALS. It was the first new treatment for the disease in over two decades, shown to slow the decline in daily functioning."
    }
  ]
}

