{
  "timeline": [
    {
      "date": "-500",
      "headline": "Ancient Near Eastern Cosmology",
      "text": "Many ancient cultures, including those in the Near East, subscribed to a flat-Earth cosmography, envisioning the Earth as a flat disk."
    },
    {
      "date": "-500",
      "headline": "Greek Philosophers Propose Spherical Earth",
      "text": "Greek philosophers such as Pythagoras and later Parmenides and Plato began to propose the idea of a spherical Earth, challenging the flat Earth model."
    },
    {
      "date": "-330",
      "headline": "Aristotle's Observations",
      "text": "Aristotle provided observational evidence for a spherical Earth, noting the shape of the Earth's shadow on the moon during a lunar eclipse."
    },
    {
      "date": "150",
      "headline": "Ptolemaic Model",
      "text": "Claudius Ptolemy's geocentric model of the universe, which included a spherical Earth, became widely accepted in the Greco-Roman world."
    },
    {
      "date": "600",
      "headline": "Medieval Islamic Astronomy",
      "text": "Islamic scholars preserved and expanded upon Greek astronomical knowledge, including the concept of a spherical Earth."
    },
    {
      "date": "1492",
      "headline": "Columbus's Voyage",
      "text": "Christopher Columbus's voyage to the Americas was based on the understanding of a spherical Earth, although he underestimated its circumference."
    },
    {
      "date": "1543",
      "headline": "Copernican Revolution",
      "text": "Nicolaus Copernicus published 'De revolutionibus orbium coelestium,' which further supported the spherical Earth model within a heliocentric system."
    },
    {
      "date": "1870",
      "headline": "Modern Flat Earth Movement",
      "text": "Samuel Rowbotham published 'Zetetic Astronomy: Earth Not a Globe,' which laid the foundation for the modern flat Earth movement."
    },
    {
      "date": "1956",
      "headline": "International Flat Earth Research Society",
      "text": "Samuel Shenton founded the International Flat Earth Research Society, promoting flat Earth theories in the modern era."
    },
    {
      "date": "2004",
      "headline": "Flat Earth Society Revived",
      "text": "The Flat Earth Society was revived by Daniel Shenton, gaining attention through the internet and social media."
    },
    {
      "date": "2015",
      "headline": "Resurgence of Flat Earth Conspiracy Theories",
      "text": "Flat Earth theories experienced a resurgence, fueled by social media platforms and public figures promoting the idea."
    }
  ]
}

