      "date": "1054",
      "headline": "Great Schism",
      "text": "The Great Schism occurred, marking the formal separation between the Eastern Orthodox Church and the Roman Catholic Church, primarily over issues of papal authority and the filioque clause."
    },
    {
      "date": "1204",
      "headline": "Sack of Constantinople",
      "text": "During the Fourth Crusade, Crusaders sacked Constantinople, leading to a deepening of the schism between the Eastern Orthodox and Roman Catholic Churches."
    },
    {
      "date": "1453",
      "headline": "Fall of Constantinople",
      "text": "The Ottoman Empire captured Constantinople, marking the end of the Byzantine Empire and a significant turning point for the Eastern Orthodox Church, which came under Muslim rule."
    },
    {
      "date": "1589",
      "headline": "Establishment of the Moscow Patriarchate",
      "text": "The Moscow Patriarchate was established, marking the independence of the Russian Orthodox Church from the Ecumenical Patriarchate of Constantinople."
    },
    {
      "date": "1923",
      "headline": "Treaty of Lausanne",
      "text": "The Treaty of Lausanne led to the population exchange between Greece and Turkey, significantly affecting the demographics of the Eastern Orthodox Church in Asia Minor."
    },
    {
      "date": "1965",
      "headline": "Mutual Lifting of Excommunications",
      "text": "Pope Paul VI and Patriarch Athenagoras I lifted the mutual excommunications that had been in place since the Great Schism of 1054, improving relations between the Eastern Orthodox and Roman Catholic Churches."
    },
    {
      "date": "2016",
      "headline": "Holy and Great Council",
      "text": "The Holy and Great Council of the Orthodox Church was held in Crete, the first such council in over a thousand years, addressing issues of modernity and church unity."
    }
  ]
}

