      "date": "-0218",
      "headline": "Crossing of the Alps",
      "text": "Hannibal famously led his army, including war elephants, across the Alps to invade Italy, marking the beginning of the Second Punic War against Rome."
    },
    {
      "date": "-0218-12",
      "headline": "Battle of the Trebia",
      "text": "Hannibal achieved a significant victory against the Roman forces at the Battle of the Trebia, his first major battle in Italy."
    },
    {
      "date": "-0217-06",
      "headline": "Battle of Lake Trasimene",
      "text": "Hannibal ambushed and decisively defeated a Roman army at Lake Trasimene, one of the largest ambushes in military history."
    },
    {
      "date": "-0216-08-02",
      "headline": "Battle of Cannae",
      "text": "Hannibal won a major victory at the Battle of Cannae, where his forces encircled and annihilated a much larger Roman army, considered one of the greatest tactical feats in military history."
    },
    {
      "date": "-0203",
      "headline": "Return to Carthage",
      "text": "Hannibal was recalled to Carthage to defend against a Roman invasion led by Scipio Africanus, marking the end of his campaign in Italy."
    },
    {
      "date": "-0202",
      "headline": "Battle of Zama",
      "text": "Hannibal was defeated by Scipio Africanus at the Battle of Zama, effectively ending the Second Punic War with a Roman victory."
    },
    {
      "date": "-0195",
      "headline": "Exile from Carthage",
      "text": "Facing political opposition and Roman demands for his surrender, Hannibal fled Carthage and lived in voluntary exile."
    },
    {
      "date": "-0183",
      "headline": "Death of Hannibal",
      "text": "Hannibal died in Libyssa (modern-day Turkey), reportedly by suicide, to avoid capture by Roman forces."
    }
  ]
}

