{
  "timeline": [
    {
      "date": "2015-09-25",
      "headline": "Adoption of the Sustainable Development Goals",
      "text": "The United Nations General Assembly formally adopted the Sustainable Development Goals (SDGs) during the United Nations Sustainable Development Summit in New York. The SDGs consist of 17 goals and 169 targets, aiming to address global challenges such as poverty, inequality, climate change, environmental degradation, peace, and justice."
    },
    {
      "date": "2015-01",
      "headline": "Transition from Millennium Development Goals to SDGs",
      "text": "The SDGs were designed to replace the Millennium Development Goals (MDGs), which were established in 2000 and expired in 2015. The SDGs build on the successes and lessons learned from the MDGs, expanding the focus to include a broader range of interconnected issues."
    },
    {
      "date": "2015-09-27",
      "headline": "2030 Agenda for Sustainable Development",
      "text": "The 2030 Agenda for Sustainable Development was adopted by all United Nations Member States. It provides a shared blueprint for peace and prosperity for people and the planet, now and into the future, with the SDGs at its core."
    },
    {
      "date": "2016-01-01",
      "headline": "Implementation of the SDGs Begins",
      "text": "The SDGs officially came into force, marking the start of a 15-year journey to achieve the goals by 2030. Countries began integrating the goals into their national policies and strategies."
    },
    {
      "date": "2019-09",
      "headline": "SDG Summit",
      "text": "The first SDG Summit was held during the United Nations General Assembly in New York. World leaders reviewed progress towards the SDGs and reaffirmed their commitment to accelerating action to achieve the goals by 2030."
    },
    {
      "date": "2020-07",
      "headline": "Impact of COVID-19 on SDGs",
      "text": "The COVID-19 pandemic posed significant challenges to the progress of the SDGs, exacerbating inequalities and impacting health, education, and economic systems worldwide. The United Nations emphasized the need for a sustainable recovery that aligns with the SDGs."
    },
    {
      "date": "2023-09",
      "headline": "SDG Summit 2023",
      "text": "The SDG Summit 2023 was held to review the progress made towards achieving the SDGs and to discuss strategies to overcome challenges, particularly in the context of the ongoing impacts of the COVID-19 pandemic and other global crises."
    }
  ]
}

