    {
      "date": "1994",
      "headline": "Formation of the Taliban",
      "text": "The Taliban was formed in southern Afghanistan by a group of Islamic students (Talibs) who were educated in traditional Islamic schools in Pakistan. The movement was led by Mullah Mohammad Omar."
    },
    {
      "date": "1996",
      "headline": "Capture of Kabul",
      "text": "The Taliban captured Kabul, the capital of Afghanistan, and established the Islamic Emirate of Afghanistan. They imposed strict Sharia law and controlled approximately 75% of the country."
    },
    {
      "date": "2001-09-11",
      "headline": "September 11 Attacks",
      "text": "Al-Qaeda, an ally of the Taliban, carried out terrorist attacks in the United States, leading to increased international scrutiny and pressure on the Taliban regime."
    },
    {
      "date": "2001-10",
      "headline": "U.S.-led Invasion of Afghanistan",
      "text": "Following the September 11 attacks, the United States led a coalition invasion of Afghanistan, aiming to dismantle al-Qaeda and remove the Taliban from power."
    },
    {
      "date": "2001-12",
      "headline": "Fall of the Taliban Regime",
      "text": "The Taliban regime was overthrown by U.S.-led coalition forces and the Northern Alliance. The Taliban leadership retreated to rural areas and neighboring Pakistan."
    },
    {
      "date": "2001-2021",
      "headline": "Taliban Insurgency",
      "text": "The Taliban engaged in a prolonged insurgency against Afghan government forces and coalition troops, aiming to regain control of Afghanistan."
    },
    {
      "date": "2020-02-29",
      "headline": "U.S.-Taliban Peace Agreement",
      "text": "The United States and the Taliban signed a peace agreement in Doha, Qatar, which included the withdrawal of U.S. troops from Afghanistan and a commitment from the Taliban to prevent terrorist activities."
    },
    {
      "date": "2021-08",
      "headline": "Taliban Recapture Kabul",
      "text": "The Taliban recaptured Kabul and took control of Afghanistan following the withdrawal of U.S. and NATO forces, marking the end of the 20-year war."
    },
    {
      "date": "2021-09",
      "headline": "Announcement of Interim Government",
      "text": "The Taliban announced an interim government for Afghanistan, with Mullah Mohammad Hassan Akhund as the acting Prime Minister."
    }
  ]
