{
  "timeline": [
    {
      "date": "1692-02",
      "headline": "Beginning of the Salem Witch Trials",
      "text": "The Salem witch trials began in February 1692 in colonial Massachusetts when several young girls in Salem Village claimed to be possessed by the devil and accused several local women of witchcraft."
    },
    {
      "date": "1692-03",
      "headline": "First Arrests",
      "text": "In March 1692, the first arrests were made. Tituba, Sarah Good, and Sarah Osborne were among the first to be accused and arrested for witchcraft."
    },
    {
      "date": "1692-05",
      "headline": "Establishment of the Court of Oyer and Terminer",
      "text": "In May 1692, Governor William Phips established a special court, the Court of Oyer and Terminer, to hear and decide witchcraft cases."
    },
    {
      "date": "1692-06",
      "headline": "First Executions",
      "text": "The first executions took place in June 1692. Bridget Bishop was the first person to be hanged after being convicted of witchcraft."
    },
    {
      "date": "1692-07",
      "headline": "Further Executions",
      "text": "In July 1692, five more people were executed, including Sarah Good and Rebecca Nurse, after being found guilty of witchcraft."
    },
    {
      "date": "1692-08",
      "headline": "Continued Executions",
      "text": "In August 1692, five more individuals were executed, including George Burroughs, a former minister, who recited the Lord's Prayer perfectly before being hanged."
    },
    {
      "date": "1692-09",
      "headline": "Giles Corey's Death",
      "text": "In September 1692, Giles Corey was pressed to death with heavy stones for refusing to enter a plea. Eight more people were also executed this month."
    },
    {
      "date": "1692-10",
      "headline": "End of the Court of Oyer and Terminer",
      "text": "Governor Phips dissolved the Court of Oyer and Terminer in October 1692, as doubts about the validity of the trials and the evidence used began to grow."
    },
    {
      "date": "1693-01",
      "headline": "Superior Court of Judicature Established",
      "text": "In January 1693, the Superior Court of Judicature was established to replace the Court of Oyer and Terminer. This court was more cautious in its proceedings."
    },
    {
      "date": "1693-05",
      "headline": "End of the Salem Witch Trials",
      "text": "By May 1693, the Salem witch trials had effectively ended. The remaining accused were released or pardoned, and the use of spectral evidence was discredited."
    }
  ]
}

