{
  "timeline": [
    {
      "date": "-1200",
      "headline": "Beginning of the Greek Dark Ages",
      "text": "The Greek Dark Ages began around 1200 BCE, following the collapse of the Mycenaean civilization. This period is characterized by a decline in population and literacy."
    },
    {
      "date": "-0800",
      "headline": "End of the Greek Dark Ages",
      "text": "The Greek Dark Ages ended around 800 BCE, marking the beginning of the Archaic period. This era saw the rise of city-states (poleis) and the reintroduction of writing."
    },
    {
      "date": "-776",
      "headline": "First Olympic Games",
      "text": "The first recorded Olympic Games were held in Olympia in 776 BCE. This event became a central part of Greek culture and was held every four years."
    },
    {
      "date": "-750",
      "headline": "Homer's Epics",
      "text": "Around 750 BCE, the epic poems 'The Iliad' and 'The Odyssey' are attributed to the poet Homer. These works are foundational texts of ancient Greek literature."
    },
    {
      "date": "-508",
      "headline": "Establishment of Athenian Democracy",
      "text": "In 508 BCE, Cleisthenes introduced a series of political reforms in Athens that laid the foundation for Athenian democracy."
    },
    {
      "date": "-490",
      "headline": "Battle of Marathon",
      "text": "In 490 BCE, the Athenians defeated the Persians at the Battle of Marathon, a pivotal moment in the Greco-Persian Wars."
    },
    {
      "date": "-480",
      "headline": "Battle of Thermopylae",
      "text": "In 480 BCE, King Leonidas of Sparta and his small force famously held off the Persian army at the Battle of Thermopylae."
    },
    {
      "date": "-480",
      "headline": "Battle of Salamis",
      "text": "In 480 BCE, the Greek fleet, led by Themistocles, defeated the Persian navy at the Battle of Salamis, a turning point in the Greco-Persian Wars."
    },
    {
      "date": "-431",
      "headline": "Start of the Peloponnesian War",
      "text": "The Peloponnesian War began in 431 BCE between Athens and Sparta, lasting until 404 BCE and leading to significant shifts in Greek power."
    },
    {
      "date": "-404",
      "headline": "End of the Peloponnesian War",
      "text": "The Peloponnesian War ended in 404 BCE with the defeat of Athens by Sparta, marking the end of the Athenian Golden Age."
    },
    {
      "date": "-338",
      "headline": "Battle of Chaeronea",
      "text": "In 338 BCE, Philip II of Macedon defeated the Greek city-states at the Battle of Chaeronea, leading to the rise of Macedonian power."
    },
    {
      "date": "-336",
      "headline": "Alexander the Great Becomes King",
      "text": "In 336 BCE, Alexander the Great ascended to the throne of Macedon, beginning his campaign to create one of the largest empires in history."
    },
    {
      "date": "-323",
      "headline": "Death of Alexander the Great",
      "text": "Alexander the Great died in 323 BCE, leading to the division of his empire among his generals, known as the Diadochi."
    },
    {
      "date": "-146",
      "headline": "Roman Conquest of Greece",
      "text": "In 146 BCE, Greece was conquered by the Roman Republic, marking the end of Greek political independence and the beginning of Roman rule."
    }
  ]
}

