{
  "timeline": [
    {
      "date": "-0000",
      "headline": "Birth of Cronus",
      "text": "Cronus was born as the youngest of the first generation of Titans, the divine descendants of the primordial deities Gaia (Earth) and Uranus (Sky)."
    },
    {
      "date": "-0000",
      "headline": "Overthrow of Uranus",
      "text": "Cronus overthrew his father Uranus, with the help of his mother Gaia, by castrating him with a sickle. This act led to Cronus becoming the ruler of the cosmos."
    },
    {
      "date": "-0000",
      "headline": "Reign during the Golden Age",
      "text": "Cronus ruled during the mythological Golden Age, a period of peace and prosperity where humans lived without need for laws or rules."
    },
    {
      "date": "-0000",
      "headline": "Prophecy of Cronus' Downfall",
      "text": "It was prophesied that Cronus would be overthrown by one of his own children, just as he had overthrown his father Uranus."
    },
    {
      "date": "-0000",
      "headline": "Devouring of His Children",
      "text": "To prevent the prophecy from coming true, Cronus swallowed each of his children at birth: Hestia, Demeter, Hera, Hades, and Poseidon."
    },
    {
      "date": "-0000",
      "headline": "Birth and Survival of Zeus",
      "text": "Rhea, Cronus' wife, saved their youngest child, Zeus, by hiding him in a cave on Crete and giving Cronus a stone wrapped in swaddling clothes to swallow instead."
    },
    {
      "date": "-0000",
      "headline": "Overthrow by Zeus",
      "text": "Zeus grew up and eventually forced Cronus to disgorge his siblings. Together, they waged war against Cronus and the Titans, known as the Titanomachy."
    },
    {
      "date": "-0000",
      "headline": "Imprisonment in Tartarus",
      "text": "After being defeated by Zeus and his siblings, Cronus was imprisoned in Tartarus, a deep abyss used as a dungeon of torment and suffering for the wicked."
    }
  ]
}

