      "headline": "First Description by John Langdon Down",
      "text": "John Langdon Down, a British physician, first described the condition that would later be known as Down syndrome. He published a paper detailing the characteristic physical features of the disorder."
    },
    {
      "date": "1959",
      "headline": "Discovery of Chromosomal Cause",
      "text": "French geneticist Jérôme Lejeune discovered that Down syndrome is caused by the presence of an extra chromosome 21, identifying it as a chromosomal disorder."
    },
    {
      "date": "1961",
      "headline": "Official Naming as Down Syndrome",
      "text": "The condition was officially named 'Down syndrome' in honor of John Langdon Down, following a letter to The Lancet by a group of geneticists."
    },
    {
      "date": "1970s",
      "headline": "Introduction of Early Intervention Programs",
      "text": "Early intervention programs began to be developed and implemented, focusing on improving the developmental outcomes for children with Down syndrome."
    },
    {
      "date": "1983",
      "headline": "Increase in Life Expectancy",
      "text": "By 1983, the life expectancy for individuals with Down syndrome had increased significantly to 25 years, due to medical advancements and improved care."
    },
    {
      "date": "2000",
      "headline": "Human Genome Project",
      "text": "The completion of the Human Genome Project provided further insights into the genetic basis of Down syndrome, aiding in research and understanding of the disorder."
    },
    {
      "date": "2011",
      "headline": "Global Down Syndrome Foundation Established",
      "text": "The Global Down Syndrome Foundation was established to improve the lives of people with Down syndrome through research, medical care, education, and advocacy."
    },
    {
      "date": "2012",
      "headline": "Trisomy 21 Research Society Founded",
      "text": "The Trisomy 21 Research Society was founded to promote research on Down syndrome and to facilitate collaboration among scientists and clinicians."
    }
  ]
}

