    {
      "date": "1800",
      "headline": "Further Migration",
      "text": "Throughout the 19th century, the Hmong continued to migrate further into Southeast Asia, establishing communities in mountainous regions."
    },
    {
      "date": "1960",
      "headline": "Involvement in the Secret War",
      "text": "During the Vietnam War, the Hmong in Laos were recruited by the CIA to fight against communist forces in what became known as the Secret War."
    },
    {
      "date": "1975",
      "headline": "Post-Vietnam War Migration",
      "text": "After the fall of Saigon and the end of the Vietnam War, many Hmong fled Laos due to persecution by the new communist government, leading to a significant diaspora, particularly to the United States."
    },
    {
      "date": "1990",
      "headline": "Resettlement in the United States",
      "text": "By the 1990s, a large number of Hmong refugees had resettled in the United States, forming significant communities in states like California, Minnesota, and Wisconsin."
    },
    {
      "date": "2004",
      "headline": "Hmong Refugee Resettlement",
      "text": "The United States began a new wave of resettlement for Hmong refugees from Thailand, leading to an increase in the Hmong American population."
    }
  ]
}

