    {
      "date": "2003-01-17",
      "headline": "Foam Strike Incident",
      "text": "During the launch of STS-107, a piece of foam insulation broke off from the Space Shuttle's external tank and struck the left wing of the orbiter. This incident was later identified as the cause of the disaster."
    },
    {
      "date": "2003-02-01",
      "headline": "Re-entry and Disintegration",
      "text": "Columbia began its re-entry into Earth's atmosphere. At approximately 8:59 a.m. EST, the orbiter disintegrated over Texas, resulting in the loss of all crew members."
    },
    {
      "date": "2003-02-01",
      "headline": "Crew Members Lost",
      "text": "The seven astronauts who perished were Rick D. Husband, William C. McCool, Michael P. Anderson, Ilan Ramon, Kalpana Chawla, David M. Brown, and Laurel B. Clark."
    },
    {
      "date": "2003-02-02",
      "headline": "Investigation Initiated",
      "text": "The Columbia Accident Investigation Board (CAIB) was established to determine the cause of the disaster and to make recommendations for the future of the Space Shuttle program."
    },
    {
      "date": "2003-08-26",
      "headline": "CAIB Report Released",
      "text": "The Columbia Accident Investigation Board released its final report, identifying the foam strike as the physical cause of the disaster and highlighting organizational and cultural issues within NASA as contributing factors."
    }
  ]
}

