{
  "timeline": [
    {
      "date": "1534-06-23",
      "headline": "Birth of Oda Nobunaga",
      "text": "Oda Nobunaga was born in Nagoya, Owari Province, Japan, as the second son of Oda Nobuhide, a deputy shugo with land holdings in Owari Province."
    },
    {
      "date": "1549",
      "headline": "Marriage to Nohime",
      "text": "Oda Nobunaga married Nohime, the daughter of Saito Dosan, a powerful daimyo of Mino Province, as part of a political alliance."
    },
    {
      "date": "1551",
      "headline": "Death of Oda Nobuhide",
      "text": "Oda Nobunaga's father, Oda Nobuhide, died, leading to a power struggle within the Oda clan."
    },
    {
      "date": "1559",
      "headline": "Consolidation of Power in Owari",
      "text": "Oda Nobunaga successfully unified the Oda clan and consolidated his power in Owari Province."
    },
    {
      "date": "1560-06-12",
      "headline": "Battle of Okehazama",
      "text": "Oda Nobunaga achieved a decisive victory against Imagawa Yoshimoto, despite being heavily outnumbered, solidifying his reputation as a formidable military leader."
    },
    {
      "date": "1567",
      "headline": "Capture of Inabayama Castle",
      "text": "Oda Nobunaga captured Inabayama Castle, the stronghold of the Saito clan, and renamed it Gifu Castle, marking his dominance over Mino Province."
    },
    {
      "date": "1568",
      "headline": "March to Kyoto",
      "text": "Oda Nobunaga marched to Kyoto and installed Ashikaga Yoshiaki as the 15th shogun, effectively gaining control over the shogunate."
    },
    {
      "date": "1571",
      "headline": "Destruction of Enryaku-ji",
      "text": "Oda Nobunaga ordered the destruction of the Enryaku-ji monastery on Mount Hiei, eliminating a powerful religious and military threat."
    },
    {
      "date": "1573",
      "headline": "Overthrow of Ashikaga Yoshiaki",
      "text": "Oda Nobunaga deposed Ashikaga Yoshiaki, ending the Ashikaga shogunate and further consolidating his power."
    },
    {
      "date": "1575-06-28",
      "headline": "Battle of Nagashino",
      "text": "Oda Nobunaga, along with Tokugawa Ieyasu, defeated the Takeda clan using innovative tactics, including the use of firearms."
    },
    {
      "date": "1582-06-21",
      "headline": "Incident at Honnō-ji",
      "text": "Oda Nobunaga was betrayed by his retainer Akechi Mitsuhide and forced to commit seppuku at Honnō-ji temple in Kyoto, marking the end of his life and reign."
    }
  ]
}

