{
  "timeline": [
    {
      "date": "1895",
      "headline": "Invention of Volleyball",
      "text": "Volleyball was invented by William G. Morgan in Holyoke, Massachusetts, USA. Originally called 'Mintonette', it was designed as an indoor sport for businessmen who found the new game of basketball too vigorous."
    },
    {
      "date": "1896",
      "headline": "First Game of Volleyball",
      "text": "The first official game of volleyball was played at Springfield College, where the name 'volleyball' was suggested by a professor, Alfred T. Halstead, after observing the volleying nature of the game."
    },
    {
      "date": "1900",
      "headline": "Introduction of Special Volleyball",
      "text": "A special ball was designed for the sport of volleyball, marking a significant development in the game's equipment."
    },
    {
      "date": "1916",
      "headline": "Introduction of Set and Spike",
      "text": "The Philippines introduced the 'set' and 'spike' offensive style of passing the ball in volleyball, which became a standard part of the game."
    },
    {
      "date": "1947",
      "headline": "Formation of FIVB",
      "text": "The Fédération Internationale de Volleyball (FIVB) was founded in Paris, France, to govern international volleyball competitions."
    },
    {
      "date": "1949",
      "headline": "First World Championships",
      "text": "The first Men's World Championship was held in Prague, Czechoslovakia, marking the beginning of international competition in volleyball."
    },
    {
      "date": "1952",
      "headline": "First Women's World Championships",
      "text": "The first Women's World Championship was held in Moscow, Soviet Union, expanding international competition to include women."
    },
    {
      "date": "1964",
      "headline": "Volleyball in the Olympics",
      "text": "Volleyball was introduced to the Olympic Games in Tokyo, Japan, as an official sport, further increasing its global popularity."
    },
    {
      "date": "1986",
      "headline": "Introduction of Beach Volleyball World Championships",
      "text": "The first official Beach Volleyball World Championships were held, marking the formal recognition of beach volleyball as a competitive sport."
    },
    {
      "date": "1996",
      "headline": "Beach Volleyball in the Olympics",
      "text": "Beach volleyball was introduced as an Olympic sport at the Atlanta Summer Olympics, highlighting its growing popularity."
    },
    {
      "date": "2004",
      "headline": "Introduction of Rally Scoring",
      "text": "The rally scoring system was introduced in volleyball, where a point is scored on every serve, regardless of which team served, to make the game faster and more exciting."
